{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2179-10-14 13:30:00",
      "speaker": "Doctor",
      "text": "Hello, I’m Dr. Lee, one of the surgical team. You’ve been admitted because of worsening hand ischemia from your right arm dialysis fistula. We’re here to help."
    },
    {
      "turn_number": 2,
      "time": "2179-10-14 13:32:00",
      "speaker": "Patient",
      "text": "Hi, yes, my hand’s been cold and numb, especially when I use it. It’s getting worse."
    },
    {
      "turn_number": 3,
      "time": "2179-10-14 13:34:00",
      "speaker": "Doctor",
      "text": "That’s called steal syndrome. The fistula is pulling too much blood away from your hand. We’re planning a procedure called fistula banding to reduce the flow."
    },
    {
      "turn_number": 4,
      "time": "2179-10-14 13:36:00",
      "speaker": "Patient",
      "text": "Will that affect my dialysis? I need that fistula to work."
    },
    {
      "turn_number": 5,
      "time": "2179-10-14 13:38:00",
      "speaker": "Doctor",
      "text": "Good question. We’ll narrow the fistula just enough to restore blood to your hand while keeping it usable for dialysis. There’s a small risk it could clot, but saving your hand comes first."
    },
    {
      "turn_number": 6,
      "time": "2179-10-14 13:40:00",
      "speaker": "Patient",
      "text": "Okay, that makes sense. When will this happen?"
    },
    {
      "turn_number": 7,
      "time": "2179-10-14 13:42:00",
      "speaker": "Doctor",
      "text": "Later today. First, we’ll get you prepped and review the consent. You’ll have hemodialysis first, as scheduled."
    },
    {
      "turn_number": 8,
      "time": "2179-10-14 13:44:00",
      "speaker": "Patient",
      "text": "I had dialysis this morning already. Is that okay?"
    },
    {
      "turn_number": 9,
      "time": "2179-10-14 13:46:00",
      "speaker": "Doctor",
      "text": "Yes, that was outpatient. Today’s session will be after your procedure, to keep your fluids and electrolytes balanced."
    },
    {
      "turn_number": 10,
      "time": "2179-10-14 13:48:00",
      "speaker": "Patient",
      "text": "Got it. And my warfarin? I’m on blood thinners."
    },
    {
      "turn_number": 11,
      "time": "2179-10-14 13:50:00",
      "speaker": "Doctor",
      "text": "We’ve held your warfarin temporarily to reduce bleeding risk during surgery. We’ll restart it soon after, once we’re sure there’s no bleeding."
    },
    {
      "turn_number": 12,
      "time": "2179-10-14 13:52:00",
      "speaker": "Patient",
      "text": "Okay, I was worried about clots with my history."
    },
    {
      "turn_number": 13,
      "time": "2179-10-14 13:54:00",
      "speaker": "Doctor",
      "text": "We know. That’s why we’re being careful. You’ll get heparin shots while off warfarin to prevent clots."
    },
    {
      "turn_number": 14,
      "time": "2179-10-14 14:15:00",
      "speaker": "Doctor",
      "text": "You’re back from the procedure. The banding was successful. We narrowed the fistula, and your radial pulse is now strong."
    },
    {
      "turn_number": 15,
      "time": "2179-10-14 14:17:00",
      "speaker": "Patient",
      "text": "How does my hand feel? It still feels cold."
    },
    {
      "turn_number": 16,
      "time": "2179-10-14 14:19:00",
      "speaker": "Doctor",
      "text": "It’s a good sign it’s still cold right now—means we reduced the flow enough. It should warm up over the next few hours as circulation adjusts."
    },
    {
      "turn_number": 17,
      "time": "2179-10-14 14:21:00",
      "speaker": "Patient",
      "text": "And the pain? It aches a bit."
    },
    {
      "turn_number": 18,
      "time": "2179-10-14 14:23:00",
      "speaker": "Doctor",
      "text": "We’ll give you Vicodin for pain. Keep your arm elevated on pillows to reduce swelling."
    },
    {
      "turn_number": 19,
      "time": "2179-10-14 16:00:00",
      "speaker": "Doctor",
      "text": "Just checking in. How’s the pain now?"
    },
    {
      "turn_number": 20,
      "time": "2179-10-14 16:02:00",
      "speaker": "Patient",
      "text": "Better, since I took the medicine. My hand feels a little warmer too."
    },
    {
      "turn_number": 21,
      "time": "2179-10-14 16:04:00",
      "speaker": "Doctor",
      "text": "That’s great progress. You’ll have dialysis in a few hours. We’ll monitor your potassium and fluids closely."
    },
    {
      "turn_number": 22,
      "time": "2179-10-14 18:30:00",
      "speaker": "Doctor",
      "text": "You finished dialysis well. Your vitals are stable, and labs look good. No signs of infection."
    },
    {
      "turn_number": 23,
      "time": "2179-10-14 18:32:00",
      "speaker": "Patient",
      "text": "Good. Should I still take my other meds like mirtazapine and quetiapine?"
    },
    {
      "turn_number": 24,
      "time": "2179-10-14 18:34:00",
      "speaker": "Doctor",
      "text": "Yes, we’ve continued all your regular medications except warfarin, which we’ll restart tomorrow."
    },
    {
      "turn_number": 25,
      "time": "2179-10-15 08:00:00",
      "speaker": "Doctor",
      "text": "Morning. Your hand is warmer, and the pulse is strong. We’re going to restart warfarin at a lower dose today."
    },
    {
      "turn_number": 26,
      "time": "2179-10-15 08:02:00",
      "speaker": "Patient",
      "text": "Is the fistula still working? I feel a buzz, but is that normal?"
    },
    {
      "turn_number": 27,
      "time": "2179-10-15 08:04:00",
      "speaker": "Doctor",
      "text": "Yes, the buzzing is a good sign—means blood is flowing. We checked with ultrasound; the fistula is open and functioning."
    },
    {
      "turn_number": 28,
      "time": "2179-10-15 08:06:00",
      "speaker": "Patient",
      "text": "That’s a relief. What about my other arm? I have a fistula there too."
    },
    {
      "turn_number": 29,
      "time": "2179-10-15 08:08:00",
      "speaker": "Doctor",
      "text": "Both fistulas are intact. For dialysis, they’ll use the right one to pull blood and the left to return it—‘1 and 1’ setup."
    },
    {
      "turn_number": 30,
      "time": "2179-10-15 10:00:00",
      "speaker": "Doctor",
      "text": "Your INR is starting to rise, which means the warfarin is working. We’ll keep monitoring it."
    },
    {
      "turn_number": 31,
      "time": "2179-10-15 10:02:00",
      "speaker": "Patient",
      "text": "And my lupus and kidney issues? Are they stable?"
    },
    {
      "turn_number": 32,
      "time": "2179-10-15 10:04:00",
      "speaker": "Doctor",
      "text": "Yes, your lupus is quiet, and your dialysis is managing your kidney failure well. The main issue was the hand ischemia, which we’ve addressed."
    },
    {
      "turn_number": 33,
      "time": "2179-10-15 14:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well. We’re planning to discharge you tomorrow morning if everything stays stable."
    },
    {
      "turn_number": 34,
      "time": "2179-10-15 14:02:00",
      "speaker": "Patient",
      "text": "What should I watch for at home?"
    },
    {
      "turn_number": 35,
      "time": "2179-10-15 14:04:00",
      "speaker": "Doctor",
      "text": "Keep an eye on your hand. If it turns cold, blue, or you can’t move it, call us. Also watch for fever, pus, or heavy bleeding from the site."
    },
    {
      "turn_number": 36,
      "time": "2179-10-15 14:06:00",
      "speaker": "Patient",
      "text": "And the dressing?"
    },
    {
      "turn_number": 37,
      "time": "2179-10-15 14:08:00",
      "speaker": "Doctor",
      "text": "Keep it dry for two days. After that, you can remove it and shower. Steri-strips will fall off on their own."
    },
    {
      "turn_number": 38,
      "time": "2179-10-15 14:10:00",
      "speaker": "Patient",
      "text": "Pain medicine? I still have some ache."
    },
    {
      "turn_number": 39,
      "time": "2179-10-15 14:12:00",
      "speaker": "Doctor",
      "text": "You’ll go home with hydrocodone for a few days. Don’t take it longer than three days unless we say so. It can cause constipation—so we’re adding docusate."
    },
    {
      "turn_number": 40,
      "time": "2179-10-15 14:14:00",
      "speaker": "Patient",
      "text": "Okay, and when do I see the surgeon again?"
    },
    {
      "turn_number": 41,
      "time": "2179-10-15 14:16:00",
      "speaker": "Doctor",
      "text": "In about two weeks. Call the office to schedule. Also, weigh yourself daily—call if you gain more than three pounds."
    },
    {
      "turn_number": 42,
      "time": "2179-10-16 09:00:00",
      "speaker": "Doctor",
      "text": "You’re cleared to go home. You’re alert, pain is controlled, and your hand is warm with good pulses."
    },
    {
      "turn_number": 43,
      "time": "2179-10-16 09:02:00",
      "speaker": "Patient",
      "text": "Thank you. I feel much better."
    },
    {
      "turn_number": 44,
      "time": "2179-10-16 09:04:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Remember: no lifting over 10 pounds for three days, no heavy exercise for two weeks, and start fistula exercises in a week."
    },
    {
      "turn_number": 45,
      "time": "2179-10-16 09:06:00",
      "speaker": "Patient",
      "text": "And no blood pressure checks or IVs in the access arm."
    },
    {
      "turn_number": 46,
      "time": "2179-10-16 09:08:00",
      "speaker": "Doctor",
      "text": "Exactly. You’ve got it. Call us with any concerns. Take care."
    },
    {
      "turn_number": 47,
      "time": "2179-10-16 09:10:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 48,
      "time": "2179-10-16 10:00:00",
      "speaker": "Doctor",
      "text": "Nurse will go over your prescriptions and discharge instructions one more time before you leave."
    },
    {
      "turn_number": 49,
      "time": "2179-10-16 10:02:00",
      "speaker": "Patient",
      "text": "Okay, I’ve got my pills and the instructions. I’ll follow up soon."
    },
    {
      "turn_number": 50,
      "time": "2179-10-16 15:15:00",
      "speaker": "Doctor",
      "text": "You’re officially discharged. Safe travels home."
    }
  ],
  "summary": {
    "admission_start": "2179-10-14 13:30:00",
    "admission_end": "2179-10-16 15:15:00",
    "summary_paragraph": "A female patient with end-stage renal disease, systemic lupus erythematosus, and a history of dialysis access complications was admitted for worsening hand ischemia due to steal syndrome from her right upper extremity AV fistula. She underwent successful fistula banding to reduce blood flow and restore perfusion to her hand. Postoperatively, she was monitored for pain, circulation, and anticoagulation management, with warfarin held temporarily and restarted the following day. She received scheduled hemodialysis during admission with stable recovery, no complications, and resolution of ischemic symptoms. She was discharged home with instructions on wound care, activity restrictions, medications including short-term pain control and stool softener, and follow-up with the surgical team in two weeks.",
    "problems": [
      "Other complications due to renal dialysis device, implant, and graft",
      "Unspecified procedure as the cause of abnormal reaction of patient, or of later complication, without mention of misadventure at time of procedure",
      "Complications of transplanted kidney",
      "Surgical operation with transplant of whole organ causing abnormal patient reaction, or later complication, without mention of misadventure at time of operation",
      "Hypertensive chronic kidney disease, unspecified, with chronic kidney disease stage V or end stage renal disease",
      "End stage renal disease",
      "Systemic lupus erythematosus",
      "Anemia, unspecified",
      "Other and unspecified hyperlipidemia",
      "Unspecified sleep apnea"
    ]
  }
}
